package com.bank.flink.cat;

import java.util.Map;

// Metadata for one table: its name and connector options.
class TableDefinition {
    private final String name;
    private final Map<String, String> options;

    TableDefinition(String name, Map<String, String> options) {
        this.name = name;
        this.options = options;
    }

    String getName() { return name; }
    Map<String, String> getOptions() { return options; }

    @Override
    public String toString() { return name + " " + options; }
}
