package com.bank.flink.cat;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// GenericInMemoryCatalog analogue: metadata lives only in this instance's heap.
class InMemoryCatalog implements Catalog {
    private static final Logger log = Logger.getLogger(InMemoryCatalog.class.getName());
    private final Map<String, TableDefinition> tables = new LinkedHashMap<>();

    @Override
    public void registerTable(TableDefinition def) {
        tables.put(def.getName(), def);
        log.info(() -> "in-memory registered " + def.getName());
    }

    @Override
    public TableDefinition lookup(String name) { return tables.get(name); }

    @Override
    public List<String> listTables() { return new ArrayList<>(tables.keySet()); }

    @Override
    public Catalog restart() {
        // A restart creates a brand-new empty heap: definitions are LOST.
        log.warning("in-memory catalog restart -> all definitions LOST");
        return new InMemoryCatalog();
    }
}
