package com.bank.flink.cat;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// HiveCatalog analogue: metadata lives in an external shared store (the Map here),
// so a restart reconnects to the same store and definitions SURVIVE.
class PersistentCatalog implements Catalog {
    private static final Logger log = Logger.getLogger(PersistentCatalog.class.getName());

    // Shared backing store (think: Hive Metastore DB). Passed in, not owned.
    private final Map<String, TableDefinition> metastore;

    PersistentCatalog(Map<String, TableDefinition> metastore) {
        this.metastore = metastore;
    }

    @Override
    public void registerTable(TableDefinition def) {
        metastore.put(def.getName(), def);
        log.info(() -> "persisted " + def.getName() + " to metastore");
    }

    @Override
    public TableDefinition lookup(String name) { return metastore.get(name); }

    @Override
    public List<String> listTables() { return new ArrayList<>(metastore.keySet()); }

    @Override
    public Catalog restart() {
        // Reconnect to the SAME metastore: definitions are still there.
        log.info("persistent catalog restart -> reconnect to metastore (survives)");
        return new PersistentCatalog(metastore);
    }
}
