package com.bank.flink.cat;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class CatalogDemo {
    private static final Logger log = Logger.getLogger(CatalogDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        TableDefinition accounts = new TableDefinition("accounts",
                Map.of("connector", "kafka", "topic", "accounts", "format", "debezium-json"));
        TableDefinition txns = new TableDefinition("transactions",
                Map.of("connector", "kafka", "topic", "txns", "format", "json"));

        // In-memory catalog: register then restart -> lost.
        Catalog mem = new InMemoryCatalog();
        mem.registerTable(accounts);
        mem.registerTable(txns);
        log.info("in-memory before restart: " + mem.listTables());
        Catalog memAfter = mem.restart();
        log.info("in-memory after restart: " + memAfter.listTables());

        // Persistent catalog: shared metastore survives restart.
        Map<String, TableDefinition> metastore = new LinkedHashMap<>();
        Catalog hive = new PersistentCatalog(metastore);
        hive.registerTable(accounts);
        hive.registerTable(txns);
        log.info("hive before restart: " + hive.listTables());
        Catalog hiveAfter = hive.restart();
        log.info("hive after restart: " + hiveAfter.listTables());
        log.info("fraud team looks up accounts: " + hiveAfter.lookup("accounts"));
    }
}

